CREATE TABLE IF NOT EXISTS cms_groups (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS cms_group_members (group_id INT NOT NULL, dealer_id INT NOT NULL, PRIMARY KEY(group_id,dealer_id), FOREIGN KEY(group_id) REFERENCES cms_groups(id), FOREIGN KEY(dealer_id) REFERENCES dealers(id));
CREATE TABLE IF NOT EXISTS cms_users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NULL UNIQUE, username VARCHAR(80) NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(300) NOT NULL, role ENUM('SUPER_ADMIN','EDITOR','DEALER_ADMIN') NOT NULL, dealer_id INT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(dealer_id) REFERENCES dealers(id));
CREATE TABLE IF NOT EXISTS cms_sessions (token_hash CHAR(64) PRIMARY KEY, user_id INT NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES cms_users(id));
CREATE TABLE IF NOT EXISTS cms_drafts (id INT AUTO_INCREMENT PRIMARY KEY, layer ENUM('COMMON','GROUP','DEALER','OVERRIDE') NOT NULL, owner_id INT NOT NULL DEFAULT 0, section_key VARCHAR(60) NOT NULL, document JSON NOT NULL, revision INT NOT NULL DEFAULT 1, remove_override BOOLEAN NOT NULL DEFAULT FALSE, updated_by INT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY draft_scope(layer,owner_id,section_key), FOREIGN KEY(updated_by) REFERENCES cms_users(id));
CREATE TABLE IF NOT EXISTS cms_publications (id INT AUTO_INCREMENT PRIMARY KEY, actor_id INT NOT NULL, target JSON NOT NULL, revisions JSON NOT NULL, recipients JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES cms_users(id));
CREATE TABLE IF NOT EXISTS cms_live (dealer_id INT NOT NULL, layer ENUM('COMMON','GROUP','DEALER','OVERRIDE') NOT NULL, section_key VARCHAR(60) NOT NULL, source_owner INT NOT NULL, revision INT NOT NULL, document JSON NOT NULL, publication_id INT NOT NULL, PRIMARY KEY(dealer_id,layer,section_key), FOREIGN KEY(dealer_id) REFERENCES dealers(id), FOREIGN KEY(publication_id) REFERENCES cms_publications(id));
CREATE TABLE IF NOT EXISTS cms_media (id INT AUTO_INCREMENT PRIMARY KEY, original_name VARCHAR(180) NOT NULL, url VARCHAR(500) NOT NULL UNIQUE, mime VARCHAR(100) NOT NULL, size_bytes INT NOT NULL, dealer_id INT NULL, created_by INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES cms_users(id), FOREIGN KEY(dealer_id) REFERENCES dealers(id));
CREATE TABLE IF NOT EXISTS cms_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id INT NULL, action VARCHAR(80) NOT NULL, details JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE enquiries ADD COLUMN address VARCHAR(1000) NOT NULL DEFAULT '', ADD COLUMN district VARCHAR(150) NOT NULL DEFAULT '', ADD COLUMN status ENUM('NEW','CONTACTED','CLOSED') NOT NULL DEFAULT 'NEW';
